return $input.all().map((item, index) => {
 const p = item.json.body ?? item.json;
 const n = p.notification ?? {}, i = p.incident ?? {}, c = p.contact;
 const reasons = [];
 if (p.source === 'demo' || i.source === 'demo' || n.source === 'demo' || i.node_id === 'DEMO-01' || (p.events ?? []).some(e => e.source === 'demo')) reasons.push('demo_rejected');
 if (typeof n.approved_by !== 'string' || !n.approved_by.trim() || !['verified','assigned'].includes(i.status)) reasons.push('not_approved');
 if (!c || c.enabled !== true || typeof c.destination !== 'string' || !/^\+[1-9]\d{7,14}$/.test(c.destination) || !['whatsapp','sms'].includes(c.channel)) reasons.push('missing_or_invalid_contact');
 if (c && (n.contact_id !== c.id || n.destination !== c.destination)) reasons.push('contact_mismatch');
 if (!n.id || !i.id || n.incident_id !== i.id) reasons.push('invalid_identity');
 if (n.channel !== 'n8n') reasons.push('not_cloud_owned');
 if (p.synthetic === true) reasons.push('synthetic_rejected');
 return {json:{dry_run:true,status:'pending_configuration',pending_configuration:['authenticated_webhook','atomic_persistent_idempotency','zavu_credentials','provider_proof_callbacks'],validation:{accepted:reasons.length === 0,reasons},dispatch_allowed:false,provider_call_performed:false,provider_id:null,sent_at:null,delivered_at:null,acknowledged_at:null},pairedItem:{item:index}};
});
